mapper.select:
/* 회원정보 존재여부 */
    SELECT 1
      FROM MEMBER
     WHERE 1=1
       AND EMAIL  = #{email}
       AND USR_ID = #{usrId}
       AND IS_DEL <> 'Y'

/* 회원정보 by usrid */
    SELECT MEM.USR_SEQ_ID
         , MEM.EMAIL
         , MEM.USR_ID
         , MEM.ROLE
      FROM MEMBER MEM
 WHERE 1=1
   AND MEM.USR_ID = #{usrId}
   AND MEM.EMAIL  = #{email}
   AND MEM.IS_DEL = 'N'

mapper.insert:
INSERT INTO MEMBER
(
  EMAIL
, USR_ID
 )
VALUES
(
  #{email}
, #{usrId}
)

mapper.update:
UPDATE MEMBER  SET
       USR_ID = #{usrId}
     , UPD_DATE_TIME = NOW()
 WHERE 1=1
   AND EMAIL = #{email}
